if(input.Customer_Name != null)
										{
											input.Display_Name_Customer = input.Customer_Name;
										}
										else
										{
											input.Display_Name_Customer = "";
										}

if(input.Customer_Name != null)
										{
											input.Display_Name_Customer = input.Customer_Name;
										}
										else
										{
											input.Display_Name_Customer = "";
										}

// =====================================================
										// CUSTOMER TYPE VALIDATION
										// =====================================================
										if(input.Customer_Type == null || input.Customer_Type == "")
										{
											alert "Please select Customer Type.";
											cancel submit;
										}
										// =====================================================
										// CASH CUSTOMER
										// =====================================================
										if(input.Customer_Type == "Cash")
										{
											if(input.Customer_Name == null || input.Customer_Name.trim() == "")
											{
												alert "Please enter Customer Name.";
												cancel submit;
											}
											input.Customer_Name = input.Customer_Name.trim();
											input.Customer = null;
											input.Credit_Allowed = false;
											input.Credit_Limit = 0;
											input.Credit_Days_Allowed = 0;
											input.Current_Outstanding_Balance = 0;
											input.Available_Credit = 0;
											input.Credit_Status = "Good Standing";
											if(input.Customer_Code == null || input.Customer_Code.trim() == "")
											{
												customer_count = Customer_Register.count();
												next_no = customer_count + 1;
												if(next_no < 10)
												{
													num_text = "00" + next_no;
												}
												else if(next_no < 100)
												{
													num_text = "0" + next_no;
												}
												else
												{
													num_text = next_no.toString();
												}
												input.Customer_Code = "CP" + num_text;
											}
										}
										// =====================================================
										// CREDIT CUSTOMER
										// =====================================================
										if(input.Customer_Type == "Credit")
										{
											if(input.Customer == null)
											{
												alert "Please select Customer.";
												cancel submit;
											}
											input.Customer_Name = ifnull(input.Customer.Party_Name_ID,"").trim();
											input.Display_Name_Customer = ifnull(input.Customer.Party_Name_ID,"").trim();
											input.Customer_Code = "";
										}
										// =====================================================
										// CUSTOMER DUPLICATE VALIDATION
										// =====================================================
										duplicate_customer_found = false;
										duplicate_customer_name = "";
										current_customer_name = ifnull(input.Customer_Name,"").trim().toLowerCase();
										for each  customer_rec in Customer_Register[ID != 0]
										{
											check_record = true;
											if(input.ID != null && customer_rec.ID == input.ID)
											{
												check_record = false;
											}
											if(check_record == true)
											{
												existing_name = ifnull(customer_rec.Customer_Name,"").trim().toLowerCase();
												if(current_customer_name != "" && existing_name == current_customer_name)
												{
													duplicate_customer_found = true;
													duplicate_customer_name = ifnull(customer_rec.Display_Name_Customer,customer_rec.Customer_Name);
													break;
												}
												if(input.Customer_Type == "Credit" && input.Customer != null)
												{
													if(customer_rec.Customer != null && customer_rec.Customer.ID == input.Customer.ID)
													{
														duplicate_customer_found = true;
														duplicate_customer_name = ifnull(customer_rec.Display_Name_Customer,customer_rec.Customer_Name);
														break;
													}
												}
											}
										}
										if(duplicate_customer_found == true)
										{
											alert "A Customer Register record already exists for this customer: " + duplicate_customer_name;
											cancel submit;
										}
										// =====================================================
										// PHONE NUMBER DUPLICATE VALIDATION
										// =====================================================
										if(input.Phone_Number != null && input.Phone_Number.toString().trim() != "")
										{
											phone_text = input.Phone_Number.toString().trim();
											if(input.ID == null)
											{
												existing_phone = Customer_Register[Phone_Number == phone_text];
												if(existing_phone.ID != null)
												{
													alert "Another customer already uses this phone number.";
													cancel submit;
												}
											}
											else
											{
												existing_phone = Customer_Register[Phone_Number == phone_text && ID != input.ID];
												if(existing_phone.ID != null)
												{
													alert "Another customer already uses this phone number.";
													cancel submit;
												}
											}
										}
										// =====================================================
										// DISPLAY NAME
										// =====================================================
										if(input.Customer_Type == "Cash")
										{
											input.Display_Name_Customer = input.Customer_Name + " - " + input.Customer_Code;
										}
										else if(input.Customer_Type == "Credit")
										{
											input.Display_Name_Customer = input.Customer_Name;
										}
										// =====================================================
										// TAX INVOICE VALIDATION
										// =====================================================
										if(input.Tax_Invoice_Required == true)
										{
											if(input.TIN_Number == null || input.TIN_Number.trim() == "")
											{
												alert "Please enter TIN Number because Tax Invoice is required.";
												cancel submit;
											}
											input.TIN_Number = input.TIN_Number.trim();
										}
										else
										{
											input.TIN_Number = "";
										}
										// =====================================================
										// CREDIT CALCULATIONS
										// =====================================================
										input.Current_Outstanding_Balance = ifnull(input.Current_Outstanding_Balance,0);
										input.Credit_Limit = ifnull(input.Credit_Limit,0);
										input.Available_Credit = input.Credit_Limit - input.Current_Outstanding_Balance;
										if(input.Credit_Allowed == true)
										{
											if(input.Current_Outstanding_Balance > input.Credit_Limit)
											{
												input.Credit_Status = "Over Limit";
											}
											else
											{
												input.Credit_Status = "Good Standing";
											}
										}
										else
										{
											input.Credit_Status = "On Hold";
										}

if(input.Customer_Type == "Cash")
										{
											show Customer_Name;
											hide Customer;
											hide Credit_Management;
											input.Customer = null;
											input.Credit_Allowed = false;
											input.Credit_Limit = null;
											input.Credit_Days_Allowed = null;
										}
										else if(input.Customer_Type == "Credit")
										{
											hide Customer_Name;
											show Customer;
											show Credit_Management;
										}
										else
										{
											hide Customer_Name;
											hide Customer;
											hide Credit_Management;
										}

if(input.Tax_Invoice_Required == true)
										{
											show TIN_Number;
										}
										else
										{
											hide TIN_Number;
											input.TIN_Number = "";
										}

// Hide everything initially
										hide Customer_Name;
										hide Customer;
										hide Customer_Code;
										hide Display_Name_Customer;
										hide Credit_Management;
										hide TIN_Number;
										disable Total_Quotations;
										disable Total_Sales_Orders;
										disable Total_Revenue;
										disable Total_Paid;
										disable Outstanding_Balance;
										disable Last_Purchase_Date;
										// Customer Type logic
										if(input.Customer_Type == "Cash")
										{
											show Customer_Name;
										}
										else if(input.Customer_Type == "Credit")
										{
											show Customer;
											show Credit_Management;
										}
										// Tax Invoice logic
										if(input.Tax_Invoice_Required == true)
										{
											show TIN_Number;
										}
										hide Back_End;
