										input.User_Name = u.get("name");
										input.User_Email = u.get("email");
										input.User_Role = u.get("role");

// =====================================================
										// VOUCHER — SET UP FORM ON CREATE
										// Record Event: Created
										// Form Event: Load of the form
										// =====================================================
										u = thisapp.audit.getLoginAuditInfo();
										input.User_Name = u.get("name");
										input.User_Email = u.get("email");
										input.User_Role = u.get("role");
										input.Created_By_Name = u.get("name");
										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;
										if(input.Voucher_Status == null)
										{
											input.Voucher_Status = "Issued";
										}
										show Document_Type;
										show Voucher_Type;
										show Employee;
										show Voucher_Number;
										enable Document_Type;
										enable Voucher_Type;
										enable Employee;
										enable Voucher_Number;
										enable Item;
										enable Quantity_To_Be_Created;

// =====================================
										// USER INPUT OF NOT CREATED
										// Show reason only when Not Created is ticked
										// =====================================
										if(input.Not_Created == true)
										{
											show Reason_Why_Not_Created;
											enable Reason_Why_Not_Created;
										}
										else
										{
											input.Reason_Why_Not_Created = "";
											hide Reason_Why_Not_Created;
											disable Reason_Why_Not_Created;
										}

if(input.Cancel_Voucher == true)
										{
											show Cancellation_Reason;
										}
										else
										{
											hide Cancellation_Reason;
											input.Cancellation_Reason = "";
										}

// ---- CONFIGURE DAY WINDOW HERE ----
										START_DAY_HOUR = 6;
										// 06:00 inclusive
										END_DAY_HOUR = 18;
										// 18:00 exclusive
										// If Date-Time In is cleared, clear dependent fields
										if(input.Date_Time_In == null)
										{
											input.Shift = null;
											input.Hours_Worked = null;
										}
										else
										{
											// -------------------------
											// 1) Shift
											// -------------------------
											hr = input.Date_Time_In.toString("HH").toLong();
											if(hr >= START_DAY_HOUR && hr < END_DAY_HOUR)
											{
												input.Shift = "Day Shift";
											}
											else
											{
												input.Shift = "Night Shift";
											}
											// -------------------------
											// 2) Hours Worked (only if Out exists)
											// -------------------------
											if(input.Date_Time_Out != null)
											{
												// Validate ordering
												if(input.Date_Time_Out < input.Date_Time_In)
												{
													alert "Date-Time Out cannot be earlier than Date-Time In.";
													input.Date_Time_Out = null;
													input.Hours_Worked = null;
												}
												else
												{
													ms = input.Date_Time_Out.toLong() - input.Date_Time_In.toLong();
													input.Hours_Worked = (ms / (1000.0 * 60.0 * 60.0)).round(2);
												}
											}
											else
											{
												input.Hours_Worked = null;
											}
										}

// Voucher → On Date_Time_Out
										// If cleared
										if(input.Date_Time_Out == null)
										{
											input.Hours_Worked = null;
											return;
										}
										// Must have In first
										if(input.Date_Time_In == null)
										{
											alert "Please enter Date-Time In first.";
											input.Date_Time_Out = null;
											input.Hours_Worked = null;
											return;
										}
										// Validate ordering
										if(input.Date_Time_Out < input.Date_Time_In)
										{
											alert "Date-Time Out cannot be earlier than Date-Time In.";
											input.Date_Time_Out = null;
											input.Hours_Worked = null;
											return;
										}
										// Compute hours
										ms = input.Date_Time_Out.toLong() - input.Date_Time_In.toLong();
										input.Hours_Worked = (ms / (1000.0 * 60.0 * 60.0)).round(2);

dt = ifnull(input.Document_Type,"").trim();
										if(dt == "Physical Voucher")
										{
											show Voucher_Type;
											enable Voucher_Type;
											enable Voucher_Number;
											input.Voucher_Type = null;
											input.Display_Name_Voucher_Type = null;
											input.Voucher_Number = null;
										}
										else if(dt == "Digital Voucher")
										{
											show Voucher_Type;
											enable Voucher_Type;
											disable Voucher_Number;
											input.Voucher_Type = null;
											input.Display_Name_Voucher_Type = null;
											input.Voucher_Number = null;
										}
										else
										{
											hide Voucher_Type;
											disable Voucher_Number;
											input.Voucher_Type = null;
											input.Display_Name_Voucher_Type = null;
											input.Voucher_Number = null;
										}

u = thisapp.audit.getLoginAuditInfo();
										input.Created_By_Name = u.get("name");
										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;
										if(input.Stock_Receiving_Book != null)
										{
											input.Display_Name_Stock_Receiving_Book = input.Stock_Receiving_Book.Voucher_Number;
											// Received By
											input.Received_By = input.Stock_Receiving_Book.Display_Name_Employee;
											// Receiving Date
											if(input.Stock_Receiving_Book.Date_Time_In != null)
											{
												input.Stock_Receiving_Date = input.Stock_Receiving_Book.Date_Time_In.toDate();
											}
											else if(input.Stock_Receiving_Book.Created_By_Time != null)
											{
												input.Stock_Receiving_Date = input.Stock_Receiving_Book.Created_By_Time.toDate();
											}
										}
										else
										{
											input.Display_Name_Stock_Receiving_Book = null;
											input.Received_By = null;
											input.Stock_Receiving_Date = null;
										}

if(input.Stock_Receiving_Book != null)
										{
											input.Display_Name_Stock_Receiving_Book = input.Stock_Receiving_Book.Voucher_Number;
											// Received By
