										// SET UP FORM - PARENT FORM LOAD
										// ===============================
										hide Display_Name_Store;
										hide Display_Name_Stock_Receiving_Book;
										hide Business_Site;
										hide Display_Name_Business_Site;
										disable Received_By;
										disable Stock_Receiving_Date;
										// ===============================
										// DEFAULT BUSINESS SITE
										// ===============================
										bs_resp = grapes_group.getBusinessSiteByAssetID("ARB282");
										if(bs_resp.get("ok") == true)
										{
											input.Business_Site = bs_resp.get("Business_Site_ID");
										}

u = thisapp.audit.getLoginAuditInfo();
										input.Created_By_Name = u.get("name");
										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;
										if(input.Item_Issuing_Voucher != null)
										{
											input.Display_Name_Item_Issuing_Voucher = input.Item_Issuing_Voucher.Voucher_Number;
											// Issued By
											input.Issued_By = input.Item_Issuing_Voucher.Display_Name_Employee;
											// Item Issuing Date
											if(input.Item_Issuing_Voucher.Date_Time_In != null)
											{
												input.Item_Issuing_Date = input.Item_Issuing_Voucher.Date_Time_In.toDate();
