if(input.Customer != null)
										{
											input.Display_Name_Customer = input.Customer.Display_Name_Customer;
											if(input.Customer.Delivery_Note_Required == true)
											{
												show Delivery_Note;
											}
											else
											{
												hide Delivery_Note;
												input.Delivery_Note = null;
											}
										}
										else
										{
											input.Display_Name_Customer = "";
											hide Delivery_Note;
											input.Delivery_Note = null;
										}

if(input.Item != null)
										{
											input.Display_Name_Item = input.Item.Item_Name + " - " + input.Item.SKU;
										}
										else
										{
											input.Display_Name_Item = "";
										}

if(input.Item == null)
										{
											alert "Item is required.";
											cancel submit;
										}
										if(input.Unit_Of_Measure == null)
										{
											alert "Unit Of Measure is required.";
											cancel submit;
										}
										if(input.Price_Type == null)
										{
											alert "Price Type is required.";
											cancel submit;
										}
										if(input.Unit_Price == null || input.Unit_Price <= 0)
										{
											alert "Unit Price must be greater than 0.";
											cancel submit;
										}
										if(input.Status == null)
										{
											input.Status = "Active";
										}
										if(input.Status == "Active")
										{
											dup = Product_Price_Register[Item == input.Item && Unit_Of_Measure == input.Unit_Of_Measure && Price_Type == input.Price_Type && Status == "Active" && ID != input.ID];
											if(dup.count() > 0)
											{
												alert "An active price already exists for this Item, Unit Of Measure and Price Type.";
												cancel submit;
											}
										}

u = thisapp.audit.getLoginAuditInfo();
										input.Created_By_Name = u.get("name");
										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;

u = thisapp.audit.getLoginAuditInfo();
										input.Updated_By_Name = u.get("name");
										input.Updated_By_Email = u.get("email");
										input.Updated_By_Time = zoho.currenttime;

//DISABLE FIELDS
										//Item Details
										disable Display_Name_Item;
										disable Display_Name_Unit_Of_Measure;
										//Back End
										disable User_Name;
										disable User_Email;
										disable User_Role;
										disable Created_By_Name;
										disable Created_By_Email;
