										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;
										input.Quantity_Returned = 0.0;
										input.Quantity_Returned_in_Base_Unit_Of_Measure = 0.0;
										// =====================================================
										// 2) NON-ISSUING REQUEST TYPES
										// =====================================================
										if(input.Request_Voucher_Type != "Employee Voucher" && input.Request_Voucher_Type != "Sales Voucher" && input.Request_Voucher_Type != "Internal Transfer")
										{
											input.Status = "Draft";
											if(input.Item != null && input.Unit_Of_Measure != null && input.Quantity != null && input.Quantity > 0)
											{
												base_qty_create = store_management.po.convert_to_base_qty_from_concrete(input.Item,input.Unit_Of_Measure,input.Quantity);
												if(base_qty_create != null && base_qty_create > 0)
												{
													input.Quantity_in_Base_Unit_Of_Measure = base_qty_create;
													input.Line_Total = (base_qty_create * ifnull(input.Cost,0.0)).round(2);
												}
											}
											info "Created as Draft. Request Type does not issue stock.";
											return;
										}
										// =====================================================
										// 3) REQUIRED FIELD CHECKS
										// =====================================================
										if(input.Issuing_Voucher == null)
										{
											info "Issuing Voucher is required.";
											return;
										}
										if(input.Request_Voucher_Type == "Employee Voucher" && input.Employee_Voucher == null)
										{
											info "Employee Voucher is required.";
											return;
										}
										if(input.Request_Voucher_Type == "Sales Voucher")
										{
											if(input.Sales_Voucher == null)
											{
												info "Sales Voucher is required.";
												return;
											}
											if(input.Item_Taken == null)
											{
												info "Item Taken is required.";
												return;
											}
										}
										if(input.Item == null || input.Unit_Of_Measure == null || input.Quantity == null || input.Quantity <= 0)
										{
											info "Item, Unit of Measure and Quantity are required.";
											return;
										}
										// =====================================================
										// 4) LOAD ISSUING HEADER + STORE
										// =====================================================
										hdr = Item_Issuing_Voucher[ID == input.Issuing_Voucher];
										if(hdr.ID == null || hdr.Store == null)
										{
											info "Header missing or Store missing.";
											return;
										}
										store_id = hdr.Store;
										// =====================================================
										// 5) STOCK CONDITION
										// =====================================================
										cond = ifnull(input.Stock_Condition,"New").trim();
										if(cond == "")
										{
											cond = "New";
											input.Stock_Condition = "New";
										}
										// =====================================================
										// 6) REFERENCE NUMBER
										// =====================================================
										ref_no = ifnull(hdr.Display_Name_Item_Issuing_Voucher,"").trim();
										if(ref_no == "")
										{
											ref_no = hdr.ID.toString();
										}
										// =====================================================
										// 7) UOM CHECK + BASE QUANTITY
										// =====================================================
										check = store_management.po.check_uom_conversion_from_concrete(input.Item,input.Unit_Of_Measure);
										if(check == null || check.get("ok") != true)
										{
											info ifnull(check.get("message"),"UOM conversion failed.");
											return;
										}
										base_qty = store_management.po.convert_to_base_qty_from_concrete(input.Item,input.Unit_Of_Measure,input.Quantity);
										if(base_qty == null || base_qty <= 0)
										{
											info "Invalid base quantity.";
											return;
										}
										input.Quantity_in_Base_Unit_Of_Measure = base_qty;
										// =====================================================
										// 8) LINE TOTAL
										// =====================================================
										line_total_val = (base_qty * ifnull(input.Cost,0.0)).round(2);
										input.Line_Total = line_total_val;
										// =====================================================
										// 9) TOOL CHECK + FINAL STATUS
										// =====================================================
										is_tool_item = false;
										if(input.Item != null && input.Item.Is_Tool == true)
										{
											is_tool_item = true;
										}
										if(input.Request_Voucher_Type == "Internal Transfer")
										{
											input.Status = "Transferred";
											input.Expected_Return_Date = null;
										}
										else if(is_tool_item == true)
										{
											input.Status = "Borrowed";
										}
										else
										{
											input.Status = "Issued";
											input.Expected_Return_Date = null;
										}
										// =====================================================
										// 10) ISSUE STOCK IN STORE MANAGEMENT
										// =====================================================
										stock_resp = store_management.stock.issue_stock_from_concrete(input.Item,store_id,input.Quantity,input.Unit_Of_Measure,cond,line_total_val,ref_no,input.ID);
										info stock_resp;
										if(stock_resp == null || stock_resp.get("ok") != true)
										{
											input.Status = "Draft";
											info "Stock issue failed: " + ifnull(stock_resp.get("message"),"No response from Store Management.");
											return;
										}
										// =====================================================
										// 11) UPDATE STOCK PREVIEW FROM RESPONSE
										// =====================================================
										input.Quantity_in_Base_Unit_Of_Measure = ifnull(stock_resp.get("base_qty"),base_qty);
										input.Store_Available_Stock = ifnull(stock_resp.get("store_stock"),0.0);
										input.Global_Available_Stock = ifnull(stock_resp.get("global_stock"),0.0);
										// =====================================================
										// 12) INTERNAL TRANSFER ONLY
										// =====================================================
										if(input.Request_Voucher_Type == "Internal Transfer")
										{
											transfer_payload = Map();
											transfer_payload.put("Source_Record_ID",input.ID);
											transfer_payload.put("Source_Form","Item Issuing Details");
											transfer_payload.put("Source_Application","Concrete Products Management");
											transfer_payload.put("Transfer_Number",ifnull(input.Item_Issuing_Number,""));
											transfer_payload.put("Transfer_Date",zoho.currentdate);
											transfer_payload.put("Issuing_Store",input.Store);
											transfer_payload.put("Item",input.Item);
											transfer_payload.put("Display_Name_Item",ifnull(input.Display_Name_Item,""));
											transfer_payload.put("Quantity",ifnull(input.Quantity,0.0));
											transfer_payload.put("Unit_Of_Measure",input.Unit_Of_Measure);
											transfer_payload.put("Display_Name_Unit_Of_Measure",ifnull(input.Display_Name_Unit_Of_Measure,""));
											transfer_payload.put("Quantity_in_Base_Unit_Of_Measure",ifnull(input.Quantity_in_Base_Unit_Of_Measure,0.0));
											transfer_payload.put("Issued_By",ifnull(input.Display_Name_Issued_By,""));
											transfer_payload.put("Stock_Condition",cond);
											transfer_payload.put("Unit_Cost",ifnull(input.Cost,0.0));
											transfer_payload.put("Transfer_Status","Not Received");
											transfer_resp = store_management.stock_transfer.create_transfer_from_item_issuing(transfer_payload);
											info transfer_resp;
											if(transfer_resp == null || transfer_resp.get("ok") != true)
											{
												info "Stock was deducted, but Stock Transfer creation failed: " + ifnull(transfer_resp.get("message"),"No response from Store Management.");
												return;
											}
										}
										// =====================================================
										// 12) UPDATE SALES VOUCHER DETAILS ISSUE STATUS
										// =====================================================
										if(input.Request_Voucher_Type == "Sales Voucher" && input.Item_Taken != null)
										{
											svd = Sales_Voucher_Details[ID == input.Item_Taken];
											if(svd.ID != null)
											{
												total_issued_base = 0.0;
												for each  issue in Item_Issuing_Details[Item_Taken == svd.ID]
												{
													total_issued_base = total_issued_base + ifnull(issue.Quantity_in_Base_Unit_Of_Measure,0.0);
												}
												required_base = ifnull(svd.Quantity_in_Base_Unit_Of_Measure,0.0);
												svd.Quantity_Issued_in_Base_Unit_Of_Measure=total_issued_base;
												not_issued_base = required_base - total_issued_base;
												if(not_issued_base < 0)
												{
													not_issued_base = 0.0;
												}
												svd.Quantity_Not_Issued_in_Base_Unit_Of_Measure=not_issued_base;
												if(total_issued_base <= 0)
												{
													svd.Issue_Status="Not Issued";
												}
												else if(total_issued_base >= required_base)
												{
													svd.Issue_Status="Fully Issued";
												}
												else
												{
													svd.Issue_Status="Partially Issued";
												}
											}
										}
										// =====================================================
										// 13) CREATE / UPDATE EMPLOYEE ISSUING DETAILS
										// =====================================================
										source_form_val = "Concrete Products - Item Issuing Details";
										if(input.Request_Voucher_Type == "Employee Voucher" && input.Employee_Voucher != null)
										{
											existing_eid = Employee_Issuing_Details[Source_Record_ID == input.ID && Source_Form == source_form_val];
											if(existing_eid.ID != null)
											{
												existing_eid.Voucher=input.Employee_Voucher;
												existing_eid.Display_Name_Voucher=input.Request_Voucher;
												existing_eid.Line_Number=input.Line_Number;
												existing_eid.Display_Name_Item=input.Display_Name_Item;
												existing_eid.Quantity=input.Quantity;
												existing_eid.Cost=input.Cost;
												existing_eid.Item_Issuing_Details=input.Item_Issuing_Number;
												existing_eid.Source_Record_ID=input.ID;
												existing_eid.Source_Form=source_form_val;
											}
											else
											{
												insert into Employee_Issuing_Details
												[
													Voucher=input.Employee_Voucher
													Display_Name_Voucher=input.Request_Voucher
													Line_Number=input.Line_Number
													Display_Name_Item=input.Display_Name_Item
													Quantity=input.Quantity
													Cost=input.Cost
													Item_Issuing_Details=input.Item_Issuing_Number
													Source_Record_ID=input.ID
													Source_Form=source_form_val
													Added_User=zoho.loginuser
