												if(balance < 0)
												{
													balance = 0.0;
												}
												prv.Total_Charges=total_charges;
												prv.Total_Amount_Allocated=amount_allocated;
												prv.Total_Amount_Not_Allocated=balance;
												if(balance <= 0)
