													total_credited = total_credited + ifnull(det2.Amount_Credited,0.0);
												}
												total_paid = round(total_paid,2);
												total_credited = round(total_credited,2);
												sv_total = round(ifnull(sv.Grand_Total,0.0),2);
												// Do not allow paid amount to exceed voucher total.
												if(total_paid > sv_total)
												{
													total_paid = sv_total;
												}
												// Credit can only cover the remaining amount after cash paid.
												max_credit = sv_total - total_paid;
												if(max_credit < 0)
												{
													max_credit = 0.0;
												}
												if(total_credited > max_credit)
												{
													total_credited = max_credit;
												}
												// Update totals.
												sv.Amount_Paid=total_paid;
												sv.Amount_Credited=total_credited;
												bal = sv_total - total_paid - total_credited;
												if(bal < 0)
