													}
													else if(total_credited > 0 && total_paid > 0)
													{
														sv.Payment_Status="Paid";
													}
													else
													{
														sv.Payment_Status="Paid";
													}
												}
												else if(total_credited > 0 && total_paid > 0)
												{
													sv.Payment_Status="Partially Paid";
												}
												else if(total_credited > 0)
												{
													sv.Payment_Status="Partially Credited";
												}
												else if(total_paid > 0)
												{
													sv.Payment_Status="Partially Paid";
												}
												else
												{
													sv.Payment_Status="Unpaid";
												}
											}
