											if(check == null || check.get("ok") != true)
											{
												errors.add("• " + ifnull(check.get("message"),"UOM conversion failed."));
											}
											else
											{
												tmp_base_qty = store_management.po.convert_to_base_qty_from_concrete(input.Item,input.Unit_Of_Measure,input.Quantity);
												if(tmp_base_qty == null)
												{
													errors.add("• Calculated base quantity is invalid.");
												}
												else
												{
													new_base_qty = tmp_base_qty.toDecimal();
													if(new_base_qty <= 0)
													{
														errors.add("• Calculated base quantity is invalid.");
													}
													else
													{
														input.Quantity_in_Base_Unit_Of_Measure = new_base_qty;
													}
												}
											}
										}
										// 12) STOCK VALIDATION
										should_validate_stock = false;
										if(req_type == "Employee Voucher")
										{
											if(input.ID == null)
											{
												should_validate_stock = true;
											}
											else if(current_status == "Approved" || current_status == "Issued" || current_status == "Borrowed")
											{
												should_validate_stock = true;
											}
										}
										else
										{
											if(input.ID != null && saved_status == "Approved" && current_status == "Approved")
											{
												should_validate_stock = true;
											}
										}
										if(should_validate_stock == true)
										{
											if(hdr != null && hdr.ID != null && hdr.Store != null && input.Item != null && new_base_qty != null && new_base_qty > 0)
											{
												stock_map = store_management.po.get_item_store_cost_from_concrete(input.Item,hdr.Store,stock_cond);
												store_stock = ifnull(stock_map.get("store_stock"),0.0).toDecimal();
												input.Store_Available_Stock = store_stock;
												input.Global_Available_Stock = ifnull(stock_map.get("global_stock"),0.0);
												old_base_qty = 0.0;
												if(input.ID != null && old_rec != null && old_rec.ID != null)
												{
													old_base_qty = ifnull(old_rec.Quantity_in_Base_Unit_Of_Measure,0.0).toDecimal();
												}
												if(req_type != "Employee Voucher" && saved_status == "Approved")
												{
													old_base_qty = 0.0;
												}
												extra_needed = new_base_qty - old_base_qty;
												if(extra_needed < 0)
												{
													extra_needed = 0.0;
												}
												if(extra_needed > 0)
												{
													if(store_stock <= 0)
													{
														errors.add("• No stock available in this Store for " + stock_cond + " condition.");
													}
													else if(extra_needed > store_stock)
													{
														errors.add("• Insufficient store stock. Required: " + extra_needed + " (Base UoM). Available: " + store_stock + " (Base UoM).");
													}
												}
											}
										}
										// 13) TOOL CHECK
										if(input.Item != null)
										{
											if(input.Item.Is_Tool == true)
											{
