											}
										}
										// 14) LINE TOTAL VALIDATION
										calc_line_total = ifnull(input.Quantity,0.0) * ifnull(input.Cost,0.0);
										if(is_tool == false && stock_cond != "Used")
										{
											if(calc_line_total <= 0)
											{
