											}
										}
										else
										{
											if(input.Line_Total == null)
											{
												input.Line_Total = 0.0;
											}
										}
										// 15) TOOL RETURN DATE VALIDATION
										if(is_tool && req_type != "Internal Transfer" && input.Expected_Return_Date == null)
										{
