										}
										// 16) EDIT ONLY CANCELLATION VALIDATION
										if(input.ID != null && input.Cancel_This_Line_Item == true)
										{
											if(input.Reason_Why_Cancelled == null || input.Reason_Why_Cancelled.trim() == "")
											{
												errors.add("• Please enter the reason why this line item was cancelled.");
											}
										}
										// FINAL
										if(errors.isEmpty() == false)
										{
											msg = "Please fix the following:\n\n";
											for each  err in errors
