											{
												errors.add("• Item Issuing Details is required.");
											}
											else
											{
												selected_issue_id = input.Item_Issuing_Details;
												issue_rec = Item_Issuing_Details[ID == selected_issue_id];
												if(issue_rec.ID == null || issue_rec.Item == null)
												{
													errors.add("• The selected Item Issuing Details record is invalid.");
												}
												else
												{
													actual_item_id = issue_rec.Item;
												}
											}
											if(input.Purchase_Order != null || input.Item != null || input.Voucher != null || input.Stock_Created != null || input.Stock_Return_Number != null || input.Item_Issuing_Details != null)
											{
												errors.add("• For Tool Return, only Tool Return fields should be filled.");
											}
										}
										else if(rtype != "")
										{
											errors.add("• Unsupported Receiving Type.");
										}
										// UOM + BASE QTY
										base_qty = null;
										input.Quantity_in_Base_Unit_Of_Measure_Received = null;
										if(actual_item_id != null && input.Unit_Of_Measure_Received != null && qty_received > 0)
										{
											check = store_management.po.check_uom_conversion_from_concrete(actual_item_id,input.Unit_Of_Measure_Received);
											if(check == null || check.get("ok") != true)
											{
												errors.add("• " + ifnull(check.get("message"),"UOM conversion failed."));
											}
											else
											{
												base_qty = store_management.po.convert_to_base_qty_from_concrete(actual_item_id,input.Unit_Of_Measure_Received,input.Quantity_Received);
												if(base_qty == null || base_qty <= 0)
												{
													errors.add("• Calculated base quantity is invalid.");
