											max_allowed = qty_remaining + old_qty_this_row;
											if(qty_received > max_allowed)
											{
												errors.add("• You cannot receive more than Quantity Remaining. Maximum allowed: " + max_allowed + ".");
											}
										}
										// TRANSFER / RETURN RULES
										is_transfer_return = false;
										if(rtype == "Internal Transfer")
										{
