										// =====================================================
										if(input.Sales_Return != null)
										{
											sales_return_rec = Sales_Return[ID == input.Sales_Return];
											if(sales_return_rec.ID != null)
											{
												grand_total = ifnull(sales_return_rec.Grand_Total,0.0);
												input.Display_Name_Bill = ifnull(sales_return_rec.Sales_Return_Number,"") + " - " + ifnull(sales_return_rec.Customer,"");
												input.Amount_Due = grand_total;
												input.Amount_Allocated = 0.0;
												input.Amount_Paid = 0.0;
												input.Balance_Due = grand_total;
											}
										}
										else
										{
											input.Display_Name_Bill = "";
											input.Amount_Due = 0.0;
											input.Amount_Allocated = 0.0;
											input.Amount_Paid = 0.0;
											input.Balance_Due = 0.0;
										}

// =====================================================
										// ON USER INPUT OF PAYMENT DOCUMENT
										// =====================================================
										if(input.Payment_Document == "Bill")
										{
											show Bill;
											hide Sales_Return;
											hide Customer_Deposit_Number;
											input.Sales_Return = null;
											input.Customer_Deposit_Number = null;
											input.Display_Name_Bill = "";
										}
										else if(input.Payment_Document == "Sales Return")
										{
											hide Bill;
											show Sales_Return;
											hide Customer_Deposit_Number;
											input.Bill = null;
											input.Customer_Deposit_Number = null;
											input.Display_Name_Bill = "";
										}
										else if(input.Payment_Document == "Cash Deposit")
										{
											hide Bill;
											hide Sales_Return;
											show Customer_Deposit_Number;
											input.Bill = null;
											input.Sales_Return = null;
											input.Display_Name_Bill = "";
										}
										else
										{
											hide Bill;
											hide Sales_Return;
											hide Customer_Deposit_Number;
											input.Bill = null;
											input.Sales_Return = null;
											input.Customer_Deposit_Number = null;
											input.Display_Name_Bill = "";
										}

if(input.Transfer_Item != null)
										{
											// =====================================================
											// DISPLAY NAME TRANSFER ITEM
											// =====================================================
											Display_Name_Transfer_Item = ifnull(input.Transfer_Item.Transfer_Number,"");
											// =====================================================
											// CLEAR FIELDS BEFORE FILLING
											// =====================================================
											input.Display_Name_Item = null;
											input.Quantity_to_Receive = null;
											input.Unit_Of_Measure_Received = null;
											input.Display_Name_Unit_Of_Measure_Received = null;
											input.Display_Name_Unit_Of_Measure_to_Receive = null;
											input.Quantity_Received = null;
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
											// =====================================================
											// ITEM DISPLAY NAME
											// =====================================================
											input.Display_Name_Item = ifnull(input.Transfer_Item.Display_Name_Item,"");
											if(input.Transfer_Item.Item != null)
											{
												itemName = ifnull(input.Transfer_Item.Item.Item_Name,"");
												itemSKU = ifnull(input.Transfer_Item.Item.SKU,"");
												if(itemName != "" && itemSKU != "")
												{
													input.Display_Name_Item = itemName + " - " + itemSKU;
												}
												else if(itemName != "")
												{
													input.Display_Name_Item = itemName;
												}
											}
											// =====================================================
											// UNIT OF MEASURE
											// =====================================================
											if(input.Transfer_Item.Unit_Of_Measure != null)
											{
												input.Unit_Of_Measure_Received = input.Transfer_Item.Unit_Of_Measure;
											}
											uom_display = ifnull(input.Transfer_Item.Display_Name_Unit_of_Measure,"");
											input.Display_Name_Unit_Of_Measure_Received = uom_display;
											input.Display_Name_Unit_Of_Measure_to_Receive = uom_display;
											// =====================================================
											// QUANTITY REMAINING
											// =====================================================
											qty_sent = ifnull(input.Transfer_Item.Quantity,0.0);
											qty_already_received = ifnull(input.Transfer_Item.Quantity_Received,0.0);
											qty_remaining = qty_sent - qty_already_received;
											if(qty_remaining < 0)
											{
												qty_remaining = 0.0;
											}
											if(qty_remaining > 0)
											{
												input.Quantity_to_Receive = qty_remaining;
											}
											else
											{
												input.Quantity_to_Receive = null;
												info "This transfer has already been fully received.";
											}
											// =====================================================
											// STOCK CONDITION
											// =====================================================
											transfer_condition = ifnull(input.Transfer_Item.Stock_Condition,"").trim();
											if(transfer_condition != "")
											{
												input.Stock_Condition = transfer_condition;
											}
											else
											{
												input.Stock_Condition = "New";
											}
											// =====================================================
											// USER ENTERS ACTUAL QUANTITY RECEIVED
											// =====================================================
											input.Quantity_Received = null;
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
										}
										else
										{
											Display_Name_Transfer_Item = null;
											input.Display_Name_Item = null;
											input.Quantity_to_Receive = null;
											input.Unit_Of_Measure_Received = null;
											input.Display_Name_Unit_Of_Measure_Received = null;
											input.Display_Name_Unit_Of_Measure_to_Receive = null;
											input.Quantity_Received = null;
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
											input.Stock_Condition = null;
										}

// =====================================================
										// ON USER INPUT OF INTERNAL TRANSFER NUMBER
										// =====================================================
										input.Transfer_Item = null;
										input.Display_Name_Item = null;
										input.Stock_Condition = null;
										input.Quantity_to_Receive = null;
										input.Quantity_Received = null;
										input.Unit_Of_Measure_Received = null;
										input.Display_Name_Unit_Of_Measure_to_Receive = null;
										input.Display_Name_Unit_Of_Measure_Received = null;
										input.Quantity_in_Base_Unit_Of_Measure_Received = null;
										input.Rate = null;
										input.Line_Total = null;
										if(input.Internal_Transfer_Number != null)
										{
											input.Display_Name_Voucher = ifnull(input.Internal_Transfer_Number.Transfer_Number,"");
										}
										else
										{
											input.Display_Name_Voucher = "";
										}

if(ifnull(input.Grand_Total,0.0) > 0)
										{
											input.Sales_Return_Status = "Not Paid";
										}
										else
										{
											input.Sales_Return_Status = "Paid";
										}

if(input.Tax_Type != null)
										{
											input.Tax_Amount = ifnull(input.Line_Total,0) * ifnull(input.Tax_Type.Tax_Rate,0) / 100;
										}
										else
										{
											input.Tax_Amount = 0;
										}

if(input.Employee_Voucher != null)
										{
											input.Display_Name_Employee_Voucher = input.Employee_Voucher.Voucher_Number + " - " + input.Employee_Voucher.Display_Name_Employee;
										}
										else
										{
											input.Display_Name_Employee_Voucher = "";
										}

if(input.Company != null)
										{
											company_name = ifnull(input.Company.Company_Name,"").trim();
											company_id = ifnull(input.Company.Company_ID,"").toString().trim();
											if(company_name != "" && company_id != "")
											{
												input.Display_Name_Company = company_name + " - " + company_id;
											}
											else if(company_name != "")
											{
												input.Display_Name_Company = company_name;
											}
											else if(company_id != "")
											{
												input.Display_Name_Company = company_id;
											}
											else
											{
												input.Display_Name_Company = null;
											}
										}
										else
										{
											input.Display_Name_Company = null;
										}

if(input.Customer_Deposit_Number != null)
										{
											input.Display_Name_Bill = ifnull(input.Customer_Deposit_Number.Customer_Deposit_Number,"") + " - " + ifnull(input.Customer_Deposit_Number.Display_Name_Customer,"");
											available_deposit = ifnull(input.Customer_Deposit_Number.Total_Amount_Not_Allocated,0.0);
											input.Amount_Due = available_deposit;
											input.Balance_Due = available_deposit;
											input.Amount_Allocated = 0.0;
											input.Amount_Paid = 0.0;
										}
										else
										{
											input.Display_Name_Bill = "";
											input.Amount_Due = 0.0;
											input.Balance_Due = 0.0;
											input.Amount_Allocated = 0.0;
											input.Amount_Paid = 0.0;
										}
